/// primitive variant that is also present, so the whole union collapses to a
/// single primitive (e.g. `"a" | string`, `"a" | "b" | string`,
/// `1 | 2 | number`, `1n | bigint`).
fn union_collapses_to_primitive(annotation: &Type) -> bool {
    let variants: Vec<Type> = annotation.flattened_union_variants().collect();

    let has_primitive = |predicate: fn(&TypeData) -> bool| {
        variants.iter().any(|variant| predicate(&variant))
    };

    let mut has_literal = false;
    for variant in &variants {
        let TypeData::Literal(lit) = &**variant else {
            continue;
        };
        let absorbed = match lit.as_ref() {
            Literal::String(_) | Literal::Template(_) => {
                has_primitive(|data| matches!(data, TypeData::String))
            }
            Literal::Number(_) => has_primitive(|data| matches!(data, TypeData::Number)),
            Literal::Boolean(_) => has_primitive(|data| matches!(data, TypeData::Boolean)),
            Literal::BigInt(_) => has_primitive(|data| matches!(data, TypeData::BigInt)),
            // Object and RegExp literals are not absorbed by a primitive.
            Literal::Object(_) | Literal::RegExp(_) => return false,
        };
        has_literal = true;
        if !absorbed {
            return false;
        }
    }

    has_literal
}

/// Builds the narrower type suggestion for the diagnostic note.
///
/// For a union annotation the suggestion is the subset of union variants that
/// are actually covered by a return statement. For any other annotation the
/// suggestion is the union of the actually-returned types. Returns `None` when
/// no concrete suggestion can be rendered (falling back to the generic note).
fn build_suggestion(effective_annotation: &Type, returns: &[Type]) -> Option<String> {
    if effective_annotation.is_union() {
        let variants: Vec<Type> = effective_annotation.flattened_union_variants().collect();
        let covered: Vec<Type> = variants
            .iter()
            .filter(|variant| {
                returns
                    .iter()
                    .any(|ret| types_match(variant, ret) || is_nonunion_wider(variant, ret))
            })
            .cloned()
            .collect();

        // Only offer a suggestion when it strictly narrows the annotation by
        // dropping at least one variant.
        if covered.is_empty() || covered.len() >= variants.len() {
            return None;
        }
        render_type_list(&covered)
    } else {
        let mut deduped: Vec<Type> = Vec::new();
        for ret in returns {
            if !deduped.iter().any(|seen| types_match(seen, ret)) {
                deduped.push(ret.clone());
            }
        }
        render_type_list(&deduped)
    }
}

/// Renders a list of types as `A | B | C`, or `None` if any variant cannot be
/// represented or the result would exceed [`MAX_DESCRIPTION_LENGTH`].
fn render_type_list(types: &[Type]) -> Option<String> {
    let mut out = String::new();
    for (index, ty) in types.iter().enumerate() {
        if index > 0 {
            out.push_str(" | ");
        }
        render_type_variant(ty, &mut out)?;
        if out.len() > MAX_DESCRIPTION_LENGTH {
            return None;
        }
    }
    (!out.is_empty()).then_some(out)
}

/// Appends the textual form of a single type variant to `out`. Returns `None`
/// for types that would be confusing or meaningless to suggest.
fn render_type_variant(ty: &Type, out: &mut String) -> Option<()> {
    match &**ty {
        TypeData::Literal(lit) => match lit.as_ref() {
            Literal::String(s) => {
                let text = s.as_str();
                // Skip values that would look confusing in a diagnostic (e.g. "...").
                if text.contains("...")
                    || text.contains("__internal")
                    || text.contains("typeof import(")
                {
                    return None;
                }
                out.push('"');
                out.push_str(text);
                out.push('"');
            }
            Literal::Number(n) => out.push_str(n.as_str()),
            Literal::Boolean(b) => out.push_str(if b.as_bool() { "true" } else { "false" }),
            _ => return None,
        },
        TypeData::Boolean => out.push_str("boolean"),
        TypeData::String => out.push_str("string"),
        TypeData::Number => out.push_str("number"),
        TypeData::BigInt => out.push_str("bigint"),
        TypeData::Null => out.push_str("null"),
        TypeData::Undefined => out.push_str("undefined"),
        _ => return None,
